const guides = JSON.parse(readFileSync(GUIDES, 'utf8'));
const queue = JSON.parse(readFileSync(QUEUE, 'utf8'));
const existing = new Set([...guides, ...queue].map((g) => g.slug));

let added = 0;
for (const art of ARTICLES) {
  if (existing.has(art.slug)) {
    console.error(`SKIP (exists): ${art.slug}`);
    continue;
  }
  guides.push(art);
  existing.add(art.slug);
  added++;
}

writeFileSync(GUIDES, JSON.stringify(guides, null, 2) + '\n');
console.log(`Published ${added} guides directly to ${GUIDES}.`);
console.log(`Guides total: ${guides.length}.`);
